   chunk=os.read(fd,min(1024*1024,4*1024*1024+1-size))
   if not chunk: break
   size+=len(chunk)
   if size>4*1024*1024: raise SystemExit("consumer renderer grew beyond bound")
   chunks.append(chunk)
